SELECT p.*, 
       u.name as authorName, u.role as authorRole, c.company_name as authorCompany,
       cat.category_name as categoryName,
       a.name as assignedUserName
FROM post p
LEFT JOIN user u ON p.user_id = u.user_id
LEFT JOIN company c ON u.company_id = c.company_id
LEFT JOIN post_category cat ON p.category_id = cat.category_id
LEFT JOIN user a ON p.assigned_user_id = a.user_id
WHERE p.is_deleted = false

    AND p.board_type = #{boardType}


    AND p.title LIKE CONCAT('%', #{keyword}, '%')


    AND p.status_id = #{statusId}


    AND p.category_id = #{categoryId}


    AND p.priority = #{priority}


    AND u.company_id = #{companyId}


    AND p.assigned_user_id = #{assignedUserId}


    AND p.created_at >= #{startDate}


    AND p.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY) 


    AND u.name LIKE CONCAT('%', #{authorName}, '%')


ORDER BY p.post_id DESC
LIMIT #{size} OFFSET #{offset}

